cat <<'EOF' > README.md
# Logomocja

Polskojęzyczna pracownia Logo do rysowania żółwiem na płaszczyźnie i w przestrzeni. Aplikacja działa lokalnie w przeglądarce; projekty i postęp wyzwań zapisuje w localStorage.

## Uruchomienie

Wymagany Bun. Uruchom "'`bun install`, a następnie `bun run dev` i otwórz adres pokazany przez Vite.

## Build

`bun run build` tworzy statyczną witrynę w `dist/`. Ścieżkę wdrożenia ustala `BASE_PATH`, np. `BASE_PATH=/Logomocja/builds/x/ bun run build`. Aplikacja używa hash URL do udostępniania programu.

## Testy

`bun run test` uruchamia zestaw testów interpretera przez Node.js.

## Język

Polecenia i składnię opisuje zakładka „Język Logo”. Przykłady są wbudowane w aplikację. API automatyzacji dostępne po załadowaniu strony: `window.logomocja.run(source, mode)` i `window.logomocja.open(source, mode)`.
EOF
cat <<'"'EOF' > test/interpreter.test.js
import {test} from 'node:test';import assert from 'node:assert/strict';import {run} from '../src/interpreter.ts';
test('draws a square',()=>{const r=run('powtorz 4 [ np 10 pw 90 ]');assert.equal(r.error,null);assert.equal(r.segments.length,4);assert.deepEqual(r.segments[0].to,[0,10,0])});
test('rejects parse errors without drawing',()=>{const r=run('np 10\\nwat');assert.equal(r.segments.length,0);assert.ok(r.error)});
test('supports repeat count and variables',()=>{const r=run('niech n 3\\npowtorz n [ np nrpowt ]');assert.equal(r.error,null);assert.deepEqual(r.segments.map(s=>s.to[1]),[1,3,6])});
test('supports procedures',()=>{const r=run('oto kw ma: a\\n np a\\njuż\\nkw 25');assert.equal(r.error,null);assert.equal(r.segments[0].to[1],25)});
test('rejects 3d-only commands in 2d',()=>{const r=run('gora 30');assert.ok(r.error);assert.equal(r.segments.length,0)});
EOF
cat <<'EOF' > vite.config.ts
import {defineConfig} from 'vite';export default defineConfig({base:process.env.BASE_PATH||'/',build:{target:'es2022'}});
EOF
bun install && bun run build && bun run test"

